	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.aPIClientSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for APIClient : " + successValue.getAPIClientId());
							  if (successValue.getAPIClientId().equals(aPIClientId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfAPIClientList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("APIClient test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on aPIClient consumed")
					);
			subscriber.aPIClientSubscribe( aPIClientId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for APIClient : " + successValue.getAPIClientId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfAPIClientList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on aPIClient for aPIClientId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a APIClient. 
	 */
	protected APIClient read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created APIClient" );

		APIClient entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read APIClient with primary key" );
		msg.append( aPIClientId );
		
		APIClientFetchOneSummary fetchOneSummary = new APIClientFetchOneSummary( aPIClientId );

		try {
			entity = APIClientService.getAPIClientInstance().getAPIClient( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found APIClient " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a APIClient.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a APIClient." );

		StringBuilder msg = new StringBuilder( "Failed to update a APIClient : " );        
		APIClient entity = read();
		UpdateAPIClientCommand command = generateUpdateCommand();
		command.setAPIClientId(entity.getAPIClientId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created APIClient." );

			// for use later on...
			aPIClientId = entity.getAPIClientId();

			APIClientService proxy = APIClientService.getAPIClientInstance();  

			proxy.updateAPIClient( command ).get();

			LOGGER.info( "-- Successfully saved APIClient - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + aPIClientId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a APIClient.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created APIClient." );

		APIClient entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read APIClient with id " + aPIClientId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read APIClient with id " + aPIClientId );

			throw e;
		}

		try{
			APIClientService.getAPIClientInstance().delete( new DeleteAPIClientCommand( entity.getAPIClientId() ) ).get();
			LOGGER.info( "-- Successfully deleted APIClient with id " + aPIClientId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete APIClient with id " + aPIClientId );

			throw e;
		}
	}

	/**
	 * get all APIClients.
	 */
	protected List<APIClient> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of APIClients:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all APIClient : " );        
		List<APIClient> collection  = new ArrayList<>();

		try {
			// call the static get method on the APIClientService
			collection = APIClientService.getAPIClientInstance().getAllAPIClient();
			assertNotNull( collection, "An Empty collection of APIClient was incorrectly returned.");
			
			// Now print out the values
			APIClient entity = null;            
			Iterator<APIClient> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAPIClientId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

